use rusqlite::{params, Connection};

static SQL_CONNECTIONS: std::sync::Mutex<std::collections::HashMap<u64, Connection>> = std::sync::Mutex::new(std::collections::HashMap::new());

fn sqlite_open(path: &str) -> u64 {
    if let Ok(conn) = Connection::open(path) {
        let id = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos() as u64;
        SQL_CONNECTIONS.lock().unwrap().insert(id, conn);
        return id;
    }
    0
}

fn sqlite_exec(id: u64, sql: &str) -> f64 {
    if let Some(conn) = SQL_CONNECTIONS.lock().unwrap().get(&id) {
        if conn.execute(sql, []).is_ok() { return 1.0; }
    }
    0.0
}
